import json

def deep_merge(base, override):
    if isinstance(base, dict) and isinstance(override, dict):
        merged = {}
        all_keys = set(base.keys()) | set(override.keys())
        for key in all_keys:
            if key in base and key in override:
                merged[key] = deep_merge(base[key], override[key])
            elif key in base:
                merged[key] = base[key]
            else:
                merged[key] = override[key]
        return merged
    elif isinstance(base, list) and isinstance(override, list):
        seen = []
        result = []
        for item in base:
            if item not in seen:
                seen.append(item)
                result.append(item)
        for item in override:
            if item not in seen:
                seen.append(item)
                result.append(item)
        return result
    else:
        return override

