import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";
        String patternStr = "^\\[(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.*)$";
        Pattern pattern = Pattern.compile(patternStr);

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorComponentCounts = new HashMap<>();
        Set<String> errorMessages = new HashSet<>();
        Map<Integer, Integer> hourCounts = new HashMap<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                Matcher matcher = pattern.matcher(line);
                if (matcher.matches()) {
                    String timestamp = matcher.group(1);
                    String level = matcher.group(2);
                    String component = matcher.group(3);
                    String message = matcher.group(4).trim();
                    int hour = Integer.parseInt(timestamp.substring(11, 13));

                    levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);
                    hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);

                    if ("ERROR".equals(level)) {
                        errorComponentCounts.put(component, errorComponentCounts.getOrDefault(component, 0) + 1);
                        errorMessages.add(message);
                    }
                }
            }
        } catch (IOException e) {
            // Handle IO errors gracefully to ensure run to completion
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();

        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();

        String topComponent = "N/A";
        int topCount = 0;
        if (!errorComponentCounts.isEmpty()) {
            Map.Entry<String, Integer> maxEntry = errorComponentCounts.entrySet().stream()
                .max(Comparator.comparingInt(Map.Entry::getValue))
                .orElse(null);
            if (maxEntry != null) {
                topComponent = maxEntry.getKey();
                topCount = maxEntry.getValue();
            }
        }
        System.out.println("Component with Most Errors: " + topComponent + " (" + topCount + " errors)");
        System.out.println();

        System.out.println("Unique Error Messages:");
        List<String> sortedMessages = new ArrayList<>(errorMessages);
        Collections.sort(sortedMessages);
        for (String msg : sortedMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        int busiestHour = -1;
        int busiestCount = 0;
        if (!hourCounts.isEmpty()) {
            Map.Entry<Integer, Integer> maxEntry = hourCounts.entrySet().stream()
                .max(Comparator.comparingInt(Map.Entry::getValue))
                .orElse(null);
            if (maxEntry != null) {
                busiestHour = maxEntry.getKey();
                busiestCount = maxEntry.getValue();
            }
        }
        System.out.println("Busiest Hour: " + String.format("%02d", Math.max(0, busiestHour)) + ":00 (" + busiestCount + " entries)");
    }
}

use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn main() -> io::Result<()> {
    let csv_path = "/tmp/…/employees.csv";

    let file = File::open(csv_path).expect("Failed to open employees.csv");
    let reader = BufReader::new(file);
    let mut lines = reader.lines();

    // Skip header
    let _header = lines.next();

    let mut dept_avg: HashMap<String, f64> = HashMap::new();
    let mut dept_count: HashMap<String, u32> = HashMap::new();
    let mut max_salary: Option<(f64, String)> = None;
    let mut total_salary_sum: f64 = 0.0;
    let mut total_employees: u32 = 0;

    for line_result in lines {
        let line = line_result.expect("Failed to read line");
        if line.trim().is_empty() {
            continue;
        }

        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 4 {
            continue;
        }

        let name = parts[1].trim();
        let department = parts[2].trim();
        let salary_str = parts[3].trim();

        let salary: f64 = salary_str.parse().expect("Invalid salary");

        let mut dept_avg_map = &mut dept_avg;
        let mut dept_count_map = &mut dept_count;

        if let Some(avg) = dept_avg_map.get_mut(department) {
            *avg += salary;
        } else {
            dept_avg_map.insert(department.to_string(), salary);
        }

        if let Some(cnt) = dept_count_map.get_mut(department) {
            *cnt += 1;
        } else {
            dept_count_map.insert(department.to_string(), 1);
        }

        total_salary_sum += salary;
        total_employees += 1;

        if max_salary.is_none() || salary > max_salary.unwrap().0 {
            max_salary = Some((salary, name.to_string()));
        }
    }

    println!("=== Salary Report ===");
    println!();

    println!("Average Salary by Department:");
    let mut depts: Vec<(String, f64)> = dept_avg.iter().map(|(k, v)| (*k, *v)).collect();
    depts.sort_by(|a, b| a.0.cmp(&b.0));
    for (dept, avg) in depts {
        let avg_str = format_avg_salary(avg);
        println!("  Department: {} ${}", dept, avg_str);
    }

    println!();

    if let Some((max_sal, max_name)) = max_salary {
        println!("Highest Paid: {} ({})", max_name, format_integer_with_commas(max_sal as i64));
    }

    println!();

    println!("Departments with >2 employees:");
    let mut large_depts: Vec<(String, u32)> = dept_count.iter().filter(|(_, &cnt)| cnt > 2).collect();
    large_depts.sort_by(|a, b| a.0.cmp(&b.0));
    for (dept, cnt) in large_depts {
        println!("  {} ({}) employees", dept, cnt);
    }

    println!();

    let total_budget = total_salary_sum as i64;
    println!("Total Budget: ${}", format_integer_with_commas(total_budget));

    Ok(())
}

fn format_integer_with_commas(n: i64) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let mut s = n.to_string();
    if s.starts_with('-') {
        s = format!("-{}", s.trim_start_matches('-'));
    }
    s.chars().rev()
        .collect::<Vec<_>>()
        .chunks(3)
        .rev()
        .collect::<Vec<_>>()
        .join(",")
}

fn format_avg_salary(val: f64) -> String {
    let s = format!("{:.2}", val);
    if let Some((int_part, frac_part)) = s.split_once('.') {
        let int_val: i64 = int_part.parse().unwrap_or(0);
        let formatted_int = format_integer_with_commas(int_val);
        return format!("{}{}", formatted_int, frac_part);
    }
    format_integer_with_commas(val as i64)
}

