fn format_integer_with_commas(n: i64) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let mut s = n.to_string();
    if s.starts_with('-') {
        s = format!("-{}", s.trim_start_matches('-'));
    }
    let chars: Vec<char> = s.chars().rev().collect();
    let mut result = String::new();
    let mut count = 0;
    for c in chars {
        if count > 0 && count % 3 == 0 {
            result.push(',');
        }
        result.push(c);
        count += 1;
    }
    result.chars().rev().collect()
}

