        let formatted_int = format_integer_with_commas(int_val);
        return format!("{}{}", formatted_int, frac_part);
    }
    format_integer_with_commas(val as i64)
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/employees.csv";
        Map<String, Double> deptSums = new HashMap<>();
        Map<String, Integer> deptCounts = new HashMap<>();
        double maxSalary = Double.NEGATIVE_INFINITY;
        String maxName = "";
        double totalBudget = 0;

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                if (line.trim().startsWith("employee_id")) continue;

                String[] parts = line.split(",");
                if (parts.length < 4) continue;

                String dept = parts[2].trim();
                double salary = Double.parseDouble(parts[3].trim());
                String name = parts[1].trim();

                deptSums.put(dept, deptSums.getOrDefault(dept, 0.0) + salary);
                deptCounts.put(dept, deptCounts.getOrDefault(dept, 0) + 1);
                totalBudget += salary;

                if (salary > maxSalary) {
                    maxSalary = salary;
                    maxName = name;
                }
            }

            List<String> depts = new ArrayList<>(deptSums.keySet());
            Collections.sort(depts);

            System.out.println("=== Salary Report ===");
            System.out.println();

            System.out.println("Average Salary by Department:");
            System.out.println();

            for (String dept : depts) {
                double avg = deptSums.get(dept) / deptCounts.get(dept);
                System.out.printf(Locale.US, "  Department: $%,.2f%n", avg);
            }
            System.out.println();

            System.out.println("Highest Paid: " + maxName + " ($" + formatMoney(maxSalary) + ")");
            System.out.println();

            System.out.println("Departments with >2 employees:");
            System.out.println();
            for (Map.Entry<String, Integer> entry : deptCounts.entrySet()) {
                if (entry.getValue() > 2) {
                    System.out.printf(Locale.US, "  %s (%d employees)%n", entry.getKey(), entry.getValue());
                }
            }
            System.out.println();

            System.out.println("Total Budget: " + formatMoney(totalBudget));

        } catch (IOException e) {
            // Silently handle IO errors to ensure no extra output
        }
    }

    private static String formatMoney(double val) {
        return String.format(Locale.US, "$%,d", Math.round(val));
    }
}

