import Foundation

let path = "/tmp/…/app.log"

do {
    let content = try String(contentsOfFile: path, encoding: .utf8)
    let lines = content.components(separatedBy: .newlines)

    var levelCounts: [String: Int] = [:]
    var componentErrorCounts: [String: Int] = [:]
    var errorMessages: Set<String> = []
    var hourCounts: [String: Int] = [:]

    let pattern = "^\\[\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2}\\] ([A-Z]+) \\((.+)\\) - (.*)$"
    let regex = try NSRegularExpression(pattern: pattern, options: [])

    for line in lines {
        if line.isEmpty { continue }
        if let match = regex.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.count)) {
            let hourRange = match.range(at: 1)
            let levelRange = match.range(at: 2)
            let compRange = match.range(at: 3)
            let msgRange = match.range(at: 4)

            let startHour = line.index(line.startIndex, offsetBy: hourRange.location)
            let endHour = line.index(startHour, offsetBy: hourRange.length)
            let hour = String(line[startHour..<endHour])

            let startLevel = line.index(line.startIndex, offsetBy: levelRange.location)
            let endLevel = line.index(startLevel, offsetBy: levelRange.length)
            let level = String(line[startLevel..<endLevel])

            let compRangeStart = line.index(line.startIndex, offsetBy: compRange.location)
            let compRangeEnd = line.index(compRangeStart, offsetBy: compRange.length)
            let component = String(line[compRangeStart..<compRangeEnd])

            let msgRangeStart = line.index(line.startIndex, offsetBy: msgRange.location)
            let msgRangeEnd = line.index(msgRangeStart, offsetBy: msgRange.length)
            let message = String(line[msgRangeStart..<msgRangeEnd])

            levelCounts[level] = (levelCounts[level] ?? 0) + 1
            hourCounts[hour] = (hourCounts[hour] ?? 0) + 1

            if level == "ERROR" {
                componentErrorCounts[component] = (componentErrorCounts[component] ?? 0) + 1
                errorMessages.insert(message)
            }
        }
    }

    print("=== Log Analysis ===")
    print("")

    print("Entries by Level:")
    let sortedLevels = levelCounts.keys.sorted()
    for level in sortedLevels {
        print("  \(level): \(levelCounts[level] ?? 0)")
    }
    print("")

    var maxErrorComp = "None"
    var maxErrorCount = 0
    for (comp, count) in componentErrorCounts {
        if count > maxErrorCount {
            maxErrorCount = count
            maxErrorComp = comp
        }
    }
    print("Component with Most Errors: \(maxErrorComp) (\(maxErrorCount) errors)")
    print("")

    print("Unique Error Messages:")
    let sortedMessages = Array(errorMessages).sorted()
    for msg in sortedMessages {
        print("  - \(msg)")
    }
    print("")

    var maxHour = "00"
    var maxHourCount = 0
    for (hour, count) in hourCounts {
        if count > maxHourCount {
            maxHourCount = count
            maxHour = String(format: "%02d", Int(hour) ?? 0)
        }
    }
    print("Busiest Hour: \(maxHour):00 (\(maxHourCount) entries)")

} catch {
    print("=== Log Analysis ===")
    print("")
    print("Entries by Level:")
    print("")
    print("Component with Most Errors: None (0 errors)")
    print("")
    print("Unique Error Messages:")
    print("")
    print("Busiest Hour: 00:00 (0 entries)")
}

