                            sb.append((char) Integer.parseInt(hex, 16));
                            break;
                        default: sb.append(next);
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            return sb.toString();
        }

        private Object parseNumber() {
            StringBuilder sb = new StringBuilder();
            if (text.charAt(pos) == '-') {
                sb.append('-');
                pos++;
            }
            while (pos < text.length() && Character.isDigit(text.charAt(pos))) {
                sb.append(text.charAt(pos++));
            }
            if (pos < text.length() && text.charAt(pos) == '.') {
                sb.append('.');
                pos++;
                while (pos < text.length() && Character.isDigit(text.charAt(pos))) {
                    sb.append(text.charAt(pos++));
                }
            }
            if (pos < text.length() && (text.charAt(pos) == 'e' || text.charAt(pos) == 'E')) {
                sb.append(text.charAt(pos++));
                if (pos < text.length() && (text.charAt(pos) == '+' || text.charAt(pos) == '-')) {
                    sb.append(text.charAt(pos++));
                }
                while (pos < text.length() && Character.isDigit(text.charAt(pos))) {
                    sb.append(text.charAt(pos++));
                }
            }
            String numStr = sb.toString();
            if (numStr.contains(".") || numStr.contains("e") || numStr.contains("E")) {
                return Double.parseDouble(numStr);
            } else {
                try {
                    return Long.parseLong(numStr);
                } catch (NumberFormatException e) {
                    return Double.parseDouble(numStr);
                }
            }
        }

        private Object parseBoolean() {
            if (text.startsWith("true", pos)) {
                pos += 4;
                return true;
            } else if (text.startsWith("false", pos)) {
                pos += 5;
                return false;
            }
            return null;
        }

        private Object parseNull() {
            if (text.startsWith("null", pos)) {
                pos += 4;
                return null;
            }
            return null;
        }
    }
}

use std::collections::{HashMap, HashSet};
use std::fs;

fn main() {
    let path = "/tmp/…/app.log";

    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return,
    };

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut component_errors: HashMap<String, usize> = HashMap::new();
    let mut error_messages: HashSet<String> = HashSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        // 1. Extract timestamp
        let bracket_end = line.find(']');
        if let Some(end) = bracket_end {
            let timestamp = &line[..end];
            // Extract Hour (index 12 to 14 in [YYYY-MM-DD HH:MM:SS])
            // YYYY-MM-DD is 10 chars, space is 1 char. Hour starts at 12.
            if timestamp.len() > 15 {
                let hour_str = &timestamp[12..14];
                let hour_key = format!("{}:00", hour_str);
                *hour_counts.entry(hour_key).or_insert(0) += 1;
            }

            // 2. Extract rest
            let rest = &line[end + 1..];
            let rest_trimmed = rest.trim_start();

            // 3. Extract Level
            let mut parts = rest_trimmed.split_whitespace();
            let level = match parts.next() {
                Some(l) => l,
                None => continue,
            };
            *level_counts.entry(level.to_string()).or_insert(0) += 1;

            // 4. Extract Component (inside parentheses)
            let level_len = level.len();
            let after_level = rest_trimmed[level_len..].trim_start();
            // after_level should start with " (component) - message"
            // Find the opening parenthesis
            let comp_start = after_level.find('(');
            let comp_end = after_level.find(')');
            if let (Some(start), Some(end)) = (comp_start, comp_end) {
                let component = &after_level[start + 1..end];
                if level == "ERROR" {
                    *component_errors.entry(component.to_string()).or_insert(0) += 1;
                }
            }

            // 5. Extract Message
            // after_level is " (component) - message"
            // We need to find " - "
            let msg_start = after_level.find(" - ");
            if let Some(msg_start_idx) = msg_start {
                let message = &after_level[msg_start_idx + 3..].trim_start();
                if level == "ERROR" {
                    error_messages.insert(message.to_string());
                }
            }
        }
    }

    // Output
    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    let mut sorted_levels: Vec<_> = level_counts.iter().collect();
    sorted_levels.sort_by(|a, b| a.0.cmp(b.0));
    for (level, count) in sorted_levels {
        println!("  {}: {}", level, count);
    }
    println!();

    // Component with Most Errors
    let mut max_comp = String::new();
    let mut max_count = 0;
    if !component_errors.is_empty() {
        let mut sorted_comps: Vec<_> = component_errors.iter().collect();
        sorted_comps.sort_by(|a, b| {
            b.1.cmp(a.1).then_with(|| a.0.cmp(b.0))
        });
        max_comp = sorted_comps[0].0.clone();
        max_count = sorted_comps[0].1;
    }
    println!("Component with Most Errors: {} ({})", max_comp, max_count);
    println!();

    // Unique Error Messages
    println!("Unique Error Messages:");
    let mut sorted_msgs: Vec<_> = error_messages.iter().collect();
    sorted_msgs.sort();
    for msg in sorted_msgs {
        println!("  - {}", msg);
    }
    println!();

    // Busiest Hour
    let mut busiest_hour = String::new();
    let mut busiest_count = 0;
    if !hour_counts.is_empty() {
        let mut sorted_hours: Vec<_> = hour_counts.iter().collect();
        sorted_hours.sort_by(|a, b| {
            b.1.cmp(a.1).then_with(|| a.0.cmp(b.0))
        });
        busiest_hour = sorted_hours[0].0.clone();
        busiest_count = sorted_hours[0].1;
    }
    println!("Busiest Hour: {} ({} entries)", busiest_hour, busiest_count);
}

