import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {

    static class Product {
        String name;
        double price;

        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            URL url = new URL("http://127.0.0.1:18923/api/products");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);

            int responseCode = conn.getResponseCode();
            if (responseCode != 200) {
                return;
            }

            StringBuilder response = new StringBuilder();
            try (BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
                String line;
                while ((line = in.readLine()) != null) {
                    response.append(line);
                }
            }
            String json = response.toString();

            List<Product> products = new ArrayList<>();
            Pattern blockPattern = Pattern.compile("\\{[^{}]*\\}");
            Matcher blockMatcher = blockPattern.matcher(json);

            Pattern namePattern = Pattern.compile("\"name\":\\s*\"([^\"]*)\"");
            Pattern pricePattern = Pattern.compile("\"price\":\\s*([\\d.]+)");

            while (blockMatcher.find()) {
                String block = blockMatcher.group();
                Matcher nameMatcher = namePattern.matcher(block);
                Matcher priceMatcher = pricePattern.matcher(block);

                String name = null;
                if (nameMatcher.find()) {
                    name = nameMatcher.group(1);
                }

                double price = 0;
                if (priceMatcher.find()) {
                    price = Double.parseDouble(priceMatcher.group(1));
                }

                if (name != null && price > 50.0) {
                    products.add(new Product(name, price));
                }
            }

            Collections.sort(products, Comparator.comparing(Product::getName));

            System.out.println("=== Filtered Products (price > $50.00) ===");
            System.out.println();

            double total = 0;
            for (Product p : products) {
                total += p.price;
            }

            for (Product p : products) {
                System.out.println("ProductName: $" + String.format(Locale.US, "%.2f", p.price));
            }

            if (!products.isEmpty()) {
                System.out.println();
            }

            System.out.println("Count: " + products.size());
            System.out.println("Total: $" + String.format(Locale.US, "%.2f", total));

        } catch (IOException e) {
            // Do nothing on error to ensure clean exit
        }
    }
}

