import Foundation

    struct Edge: Codable {
        let from: String
        let to: String
        let weight: Double
    }

    struct Graph: Codable {
        let nodes: [String]
        let edges: [Edge]
    }

    let filePath = "/tmp/…/graph.json"

    guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)) else {
        return
    }

    let graph = try? JSONDecoder().decode(Graph.self, from: data)
    guard let graph = graph else { return }

    // Build Adjacency List
    var adj: [String: [(String, Double)]] = [:]
    for node in graph.nodes {
        adj[node] = []
    }

    for edge in graph.edges {
        let w = edge.weight
        if edge.from == edge.to { continue } // Self loop, ignore or handle
        adj[edge.from]!.append((edge.to, w))
        adj[edge.to]!.append((edge.from, w)) // Undirected
    }

    let startNode = "A"
    var distances: [String: Double] = [:]
    for node in graph.nodes {
        distances[node] = Double.infinity
    }
    distances[startNode] = 0.0

    var visited: Set<String> = []

    // Dijkstra O(V^2)
    for _ in 0..<graph.nodes.count {
        var u: String?
        var minDist = Double.infinity

        for node in graph.nodes {
            if !visited.contains(node), distances[node]! < minDist {
                minDist = distances[node]!
                u = node
            }
        }

        if u == nil || visited.contains(u!) {
            break
        }

        visited.insert(u!)

        if let neighbors = adj[u] {
            for (v, w) in neighbors {
                if distances[v]! > distances[u]! + w {
                    distances[v]! = distances[u]! + w
                }
            }
        }
    }

    let title = "=== Shortest Paths from A ==="
    print(title)
    print("")
    for node in graph.nodes.sorted() {
        let dist = distances[node] ?? Double.infinity
        if dist == Double.infinity {
            print("A -> \(node): unreachable")
        } else {
            // Format number nicely (remove .0 if integer)
            let distStr = Double.isFinite(dist) && dist.truncatingRemainder(dividingBy: 1) == 0 
                ? String(Int(dist))
                : String(dist)
            print("A -> \(node): \(distStr)")
        }
    }

