import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) {
        try {
            String os = runCommand("uname", "-s");
            String arch = runCommand("uname", "-m");
            String user = runCommand("whoami");
            String host = runCommand("hostname");

            StringBuilder jsonBuilder = new StringBuilder();
            jsonBuilder.append("{\n");
            jsonBuilder.append("  \"hostname\": \"").append(escapeJson(host)).append("\",\n");
            jsonBuilder.append("  \"os\": \"").append(escapeJson(os)).append("\",\n");
            jsonBuilder.append("  \"architecture\": \"").append(escapeJson(arch)).append("\",\n");
            jsonBuilder.append("  \"username\": \"").append(escapeJson(user)).append("\n");
            jsonBuilder.append("}");

            System.out.println(jsonBuilder.toString());
        } catch (Exception e) {
            System.out.println("{\n  \"hostname\": \"\",\n  \"os\": \"\",\n  \"architecture\": \"\",\n  \"username\": \"\"\n}");
        }
    }

    private static String runCommand(String... command) throws IOException {
        ProcessBuilder pb = new ProcessBuilder(command);
        Process p = pb.start();
        StringBuilder sb = new StringBuilder();
        try (InputStream inputStream = p.getInputStream();
             BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
        }
        return sb.toString().trim();
    }

    private static String escapeJson(String str) {
        if (str == null) return "";
        return str.replace("\\", "\\\\")
                  .replace("\"", "\\\"")
                  .replace("\n", "\\n")
                  .replace("\r", "\\r")
                  .replace("\t", "\\t");
    }
}

