#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <climits>

struct Edge {
    char *to;
    int weight;
    struct Edge *next;
};

struct Node {
    char *name;
    int dist;
    int visited;
    struct Edge *adj;
};

char *skip_ws(char **p) {
    while (**p != '\0' && isspace(**p)) (*p)++;
    return *p;
}

char *find_key(char **p, const char *key) {
    *p = skip_ws(p);
    char *pos = strstr(*p, key);
    if (pos == NULL) return NULL;
    *p = pos + strlen(key);
    *p = skip_ws(p);
    if (*p != ':') return NULL;
    (*p)++;
    *p = skip_ws(p);
    return *p;
}

char *read_string(char **p) {
    *p = skip_ws(p);
    if (**p != '"') return NULL;
    (*p)++;
    char *start = *p;
    while (**p != '"') (*p)++;
    (*p)++;
    return start;
}

long read_int(char **p) {
    *p = skip_ws(p);
    char *p_start = *p;
    if (**p == '-') (*p)++;
    while (isdigit(**p)) (*p)++;
    long val = 0;
    while (p_start < *p) {
        val = val * 10 + (*p_start - '0');
        p_start++;
    }
    if (*p_start == '-') val = -val;
    return val;
}

int compare_name_info(const void *a, const void *b) {
    struct NameInfo *na = (struct NameInfo *)a;
    struct NameInfo *nb = (struct NameInfo *)b;
    return strcmp(na->name, nb->name);
}

