        fclose(f);
        return 1;
    }
    fread(buffer, 1, fsize, f);
    buffer[fsize] = '\0';
    fclose(f);

    char *p = buffer;
    char *p_save = p;
    skip_ws(&p);
    if (strstr(p, "nodes") != NULL) {
        p = strstr(p, "nodes");
        p += 5;
        p = skip_ws(&p);
        if (*p == ':') p++;
        p = skip_ws(&p);
        if (*p == '[') p++;
    }

    int node_count = 0;
    char **node_names = NULL;
    struct Node *nodes = NULL;
    struct NameInfo *name_info = NULL;

    while (*p != '\0' && *p != ']') {
        char *name = read_string(&p);
        if (name == NULL) break;
        char *name_copy = malloc(strlen(name) + 1);
        strcpy(name_copy, name);

        node_names = realloc(node_names, (node_count + 1) * sizeof(char *));
        node_names[node_count] = name_copy;

        struct Node *n = malloc(sizeof(struct Node));
        n->name = name_copy;
        n->dist = INT_MAX;
        n->visited = 0;
        n->adj = NULL;
        nodes = realloc(nodes, (node_count + 1) * sizeof(struct Node));
        nodes[node_count] = *n;

