        p = skip_ws(&p);
        if (*p == ',') p++;
    }

    if (strstr(p, "edges") != NULL) {
        p = strstr(p, "edges");
        p += 5;
        p = skip_ws(&p);
        if (*p == ':') p++;
        p = skip_ws(&p);
        if (*p == '[') p++;
    }

    while (*p != '\0' && *p != ']') {
        if (*p == '{') p++;
        p = skip_ws(&p);
        char *from = find_key(&p, "from");
        char *to = find_key(&p, "to");
        long weight = read_int(&p);

        if (from && to) {
            struct Node *from_node = NULL;
            for (int i = 0; i < node_count; i++) {
                if (strcmp(nodes[i].name, from) == 0) {
                    from_node = &nodes[i];
                    break;
                }
            }
            struct Node *to_node = NULL;
            for (int i = 0; i < node_count; i++) {
                if (strcmp(nodes[i].name, to) == 0) {
                    to_node = &nodes[i];
                    break;
                }
            }
            if (from_node && to_node) {
                struct Edge *e = malloc(sizeof(struct Edge));
                e->to = malloc(strlen(to) + 1);
                strcpy(e->to, to);
                e->weight = (int)weight;
                e->next = from_node->adj;
                from_node->adj = e;

                e = malloc(sizeof(struct Edge));
                e->to = malloc(strlen(from) + 1);
                strcpy(e->to, from);
                e->weight = (int)weight;
                e->next = to_node->adj;
                to_node->adj = e;
            }
        }
        p = skip_ws(&p);
        if (*p == ',') p++;
    }

    int start_idx = -1;
    for (int i = 0; i < node_count; i++) {
        if (strcmp(nodes[i].name, "A") == 0) {
            start_idx = i;
            break;
        }
    }

