        for (int j = 0; j < node_count; j++) {
            if (!nodes[j].visited && nodes[j].dist < min_dist) {
                min_dist = nodes[j].dist;
                u = j;
            }
        }
        if (u == -1) break;
        nodes[u].visited = 1;
        struct Edge *e = nodes[u].adj;
        while (e) {
            int v = -1;
            for (int k = 0; k < node_count; k++) {
                if (strcmp(nodes[k].name, e->to) == 0) {
                    v = k;
                    break;
                }
            }
            if (v != -1) {
                if (nodes[u].dist + e->weight < nodes[v].dist) {
                    nodes[v].dist = nodes[u].dist + e->weight;
                }
            }
            e = e->next;
        }
    }

    qsort(name_info, node_count, sizeof(struct NameInfo), compare_name_info);

    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < node_count; i++) {
        struct NameInfo *ni = &name_info[i];
        int idx = ni->index;
        int dist = nodes[idx].dist;
        if (dist == INT_MAX) {
            printf("A -> %s: infinity\n", ni->name);
        } else {
            printf("A -> %s: %d\n", ni->name, dist);
        }
    }

    free(buffer);
    free(node_names);
    free(nodes);
    free(name_info);
    return 0;
}

