fn walk_dir(current: &Path, base: &Path, map: &mut BTreeMap<String, Vec<FileStatsInfo>>) {
    for entry_result in fs::read_dir(current).ok() {
        if let Ok(entry) = entry_result {
            let metadata = match entry.symlink_metadata() {
                Ok(m) => m,
                Err(_) => continue,
            };

            if metadata.is_symlink() {
                continue;
            }

            if metadata.is_dir() {
                walk_dir(&entry.path(), base, map);
            } else if metadata.is_file() {
                if let Ok(rel_path) = entry.path().strip_prefix(base) {
                    let rel_path_str = rel_path.to_string_lossy().to_string();
                    let file_path = entry.path();

                    if let Ok(metadata) = fs::metadata(&file_path) {
                        if metadata.is_file() {
                            let bytes = match fs::read(&file_path) {
                                Ok(b) => b,
                                Err(_) => continue,
                            };

                            let line_count = bytes.iter().filter(|b| **b == b'\n').count() as u64;
                            let byte_count = bytes.len() as u64;

                            let ext = file_path.extension()
                                .map(|e| format!(".{}", e.to_string_lossy()))
