use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

struct FileStatsInfo {
    rel_path: String,
    lines: u64,
    bytes: u64,
}

fn walk_dir(current: &Path, base: &Path, map: &mut BTreeMap<String, Vec<FileStatsInfo>>) {
    if let Ok(mut dir) = fs::read_dir(current) {
        for entry_result in dir {
            if let Ok(entry) = entry_result {
                let metadata = match entry.symlink_metadata() {
                    Ok(m) => m,
                    Err(_) => continue,
                };

                if metadata.is_symlink() {
                    continue;
                }

                if metadata.is_dir() {
                    walk_dir(&entry.path(), base, map);
                } else if metadata.is_file() {
                    if let Ok(rel_path) = entry.path().strip_prefix(base) {
                        let rel_path_str = rel_path.to_string_lossy().to_string();
                        let file_path = entry.path();

                        if let Ok(metadata) = fs::metadata(&file_path) {
                            if metadata.is_file() {
                                let bytes = match fs::read(&file_path) {
                                    Ok(b) => b,
                                    Err(_) => continue,
                                };

                                let line_count = bytes.iter().filter(|b| **b == b'\n').count() as u64;
                                let byte_count = bytes.len() as u64;

                                let ext = file_path.extension()
                                    .map(|e| format!(".{}", e.to_string_lossy()))
                                    .unwrap_or_else(|| "".to_string());

                                let info = FileStatsInfo {
                                    rel_path: rel_path_str,
                                    lines: line_count,
                                    bytes: byte_count,
                                };

                                let files = map.entry(ext).or_insert_with(Vec::new);
                                files.push(info);
                            }
                        }
                    }
                }
            }
        }
    }
}

fn main() {
    let base = PathBuf::from("/tmp/…/project_tree");

    let mut map: BTreeMap<String, Vec<FileStatsInfo>> = BTreeMap::new();

    if base.exists() && base.is_dir() {
        walk_dir(&base, &base, &mut map);
    }

    let mut total_files = 0u64;
    let mut total_lines = 0u64;
    let mut total_chars = 0u64;

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, mut files) in map {
        files.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));

